unsafe fn hm_hash(mut key: *const c_char) -> c_ulong {
    let mut hash: c_ulong = 5381 as c_ulong;
    let mut c: c_int = 0;
    loop {
        let fresh9 = key;
        key = key.offset(1);
        c = *fresh9 as c_int;
        if !(c != 0) {
            break;
        }
        hash = (hash << 5 as c_int)
            .wrapping_add(hash)
            .wrapping_add(c as c_ulong);
    }
    return hash;
}
